import os
from sellapp_sdk import SellAppClient

client = SellAppClient(base_url=os.environ["SELLAPP_API_BASE_URL"], api_key=os.environ["SELLAPP_API_KEY"], store=os.environ["SELLAPP_STORE"])

result = client.product_variants.batch_create(
    product=1,
    resources=[
        {
            "title": "Default",
            "description": "Default product variant.",
            "deliverable": {
                "types": ["TEXT"],
                "data": {"serials": ["SERIAL-001"], "parsingMode": "NEW_LINE", "removeDuplicate": True}
            },
            "pricing": {"humble": False, "price": {"price": 1000, "currency": "USD"}},
            "payment_methods": ["PAYPAL"]
        }
    ]
)
print(result)

import os
from sellapp_sdk import SellAppClient

client = SellAppClient(base_url=os.environ["SELLAPP_API_BASE_URL"], api_key=os.environ["SELLAPP_API_KEY"], store=os.environ["SELLAPP_STORE"])

result = client.orders.search(
    filters=[
        {"field": "transaction_id", "operator": "contains", "value": "pi_3Example"},
        {"field": "status", "operator": "in", "value": ["COMPLETED"]}
    ],
    sort=[{"field": "created_at", "direction": "desc"}],
    pagination={"page": 1, "limit": 25}
)
print(result)

